Given an integer n, return all numbers less than or equal to n in increasing order such that the absolute difference between adjacent digits of every number is exactly 1.Note:  Only numbers with at least two digits are considered valid.Examples:Input: n = 20Output: [10, 12]Explanation: The absolute difference between adjacent digits in 10 is |1 - 0| = 1, and in 12 is |1 - 2| = 1.Input: n = 9Output: []Explanation: No such valid number exist in the range 1 to 9. Try It YourselfTable of Content[Naive Approach] Check Every Number - O(n × d) Time and O(1) Space[Expected Approach] Generate Valid Numbers using BFS - O(k) Time and O(k) Space[Alternative Approach] Using DFS / Backtracking - O(k log k) Time and O(d) Space[Naive Approach] Check Every Number - O(n × d) Time and O(1) SpaceThe idea is to iterate through every number from 10 to n and check whether the absolute difference between every pair of adjacent digits is exactly 1. If the condition is satisfied, include the number in the result; otherwise, ignore it.Working of Approach:Traverse every number from 10 to n.Extract adjacent digits one by one using modulo and division.Check whether the absolute difference of every adjacent digit pair is 1.If all pairs satisfy the condition, add the number to the answer.Return the final list.
            C++

    #include <iostream>
#include <vector>
#include <cmath>
using namespace std;

// Function to check whether adjacent digits differ by exactly 1.
bool isValid(int num)
{

    while (num >= 10)
    {
        int last = num % 10;
        int secondLast = (num / 10) % 10;

        if (abs(last - secondLast) != 1)
            return false;

        num /= 10;
    }

    return true;
}

vector<int> absDifOne(int n)
{

    vector<int> res;

    // Check every number from 10 to n.
    for (int i = 10; i <= n; i++)
    {
        if (isValid(i))
            res.push_back(i);
    }

    return res;
}

int main()
{

    int n = 20;

    vector<int> res = absDifOne(n);

    cout << "[";

    for (int i = 0; i < res.size(); i++)
    {
        cout << res[i];
        if (i + 1 < res.size())
            cout << ", ";
    }

    cout << "]";

    return 0;
}


