    #include <iostream>
#include <vector>
#include <queue>
using namespace std;

vector<int> absDifOne(int n)
{
    vector<int> res;
    queue<int> q;

    // Push all single-digit numbers into the queue.
    for (int i = 1; i <= 9; i++)
    {
        q.push(i);
    }

    while (!q.empty())
    {
        int curr = q.front();
        q.pop();

        // Skip numbers greater than n.
        if (curr > n)
        {
            continue;
        }

        // Store valid numbers having at least two digits.
        if (curr > 9)
        {
            res.push_back(curr);
        }

        int lastDigit = curr % 10;

        // Generate the next number with lastDigit - 1.
        if (lastDigit > 0)
        {
            q.push(curr * 10 + lastDigit - 1);
        }

        // Generate the next number with lastDigit + 1.
        if (lastDigit < 9)
        {
            q.push(curr * 10 + lastDigit + 1);
        }
    }

    return res;
}

